package com.spas.crss.model;

public class Course {

    private int courseId;
    private String courseTitle;
    private String courseCode;
    private int creditHours;
    private String description;

    // Default constructor
    public Course() {
    }

    // Constructor without ID (ID generated by database)
    public Course(String courseTitle, String courseCode,
                  int creditHours, String description) {

        this.courseTitle = courseTitle;
        this.courseCode = courseCode;
        this.creditHours = creditHours;
        this.description = description;
    }

    // Constructor with ID
    public Course(int courseId, String courseTitle,
                  String courseCode, int creditHours,
                  String description) {

        this.courseId = courseId;
        this.courseTitle = courseTitle;
        this.courseCode = courseCode;
        this.creditHours = creditHours;
        this.description = description;
    }

    // Getters and Setters
    public int getCourseId() {
        return courseId;
    }

    public void setCourseId(int courseId) {
        this.courseId = courseId;
    }

    public String getCourseTitle() {
        return courseTitle;
    }

    public void setCourseTitle(String courseTitle) {
        this.courseTitle = courseTitle;
    }

    public String getCourseCode() {
        return courseCode;
    }

    public void setCourseCode(String courseCode) {
        this.courseCode = courseCode;
    }

    public int getCreditHours() {
        return creditHours;
    }

    public void setCreditHours(int creditHours) {
        this.creditHours = creditHours;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }
}